use clap::{Arg, ArgAction, Command};
use std::io::{IsTerminal, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command as ProcCommand, Stdio};

const VERSION_OUTPUT: &str = "run-kit 0.3.2\nUniversal multi-language runner and smart REPL\nauthor: Esubalew Chekol <esubalewchekol6@gmail.com>\nhomepage: https://esubalew.et\nrepository: https://github.com/Esubaalew/run\nlicense: Apache-2.0\ncommit: 2b5ade5f (2026-06-11T19:26:04+00:00, dirty: clean)\nbuilt: 2026-08-10T23:14:37.189187652+00:00 [release for x86_64-unknown-linux-gnu]\nrustc: rustc 1.92.0 (ded5c06cf 2025-12-08)\n";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Lang {
    Bash, C, Cpp, Crystal, Csharp, Dart, Elixir, Go, Groovy, Haskell, Java, Javascript, Julia, Kotlin, Lua, Nim, Perl, Php, Python, R, Ruby, Rust, Swift, Typescript, Zig,
}

impl Lang {
    fn canonical(&self) -> &'static str {
        match self {
            Lang::Bash => "bash",
            Lang::C => "c",
            Lang::Cpp => "cpp",
            Lang::Crystal => "crystal",
            Lang::Csharp => "csharp",
            Lang::Dart => "dart",
            Lang::Elixir => "elixir",
            Lang::Go => "go",
            Lang::Groovy => "groovy",
            Lang::Haskell => "haskell",
            Lang::Java => "java",
            Lang::Javascript => "javascript",
            Lang::Julia => "julia",
            Lang::Kotlin => "kotlin",
            Lang::Lua => "lua",
            Lang::Nim => "nim",
            Lang::Perl => "perl",
            Lang::Php => "php",
            Lang::Python => "python",
            Lang::R => "r",
            Lang::Ruby => "ruby",
            Lang::Rust => "rust",
            Lang::Swift => "swift",
            Lang::Typescript => "typescript",
            Lang::Zig => "zig",
        }
    }
    fn from_str(s: &str) -> Option<Lang> {
        let l = s.to_ascii_lowercase();
        match l.as_str() {
            "bash" | "sh" | "shell" => Some(Lang::Bash),
            "c" => Some(Lang::C),
            "cpp" | "c++" => Some(Lang::Cpp),
            "crystal" | "cr" => Some(Lang::Crystal),
            "csharp" | "cs" | "c#" => Some(Lang::Csharp),
            "dart" => Some(Lang::Dart),
            "elixir" | "ex" | "exs" => Some(Lang::Elixir),
            "go" | "golang" => Some(Lang::Go),
            "groovy" => Some(Lang::Groovy),
            "haskell" | "hs" => Some(Lang::Haskell),
            "java" => Some(Lang::Java),
            "javascript" | "js" | "node" => Some(Lang::Javascript),
            "julia" | "jl" => Some(Lang::Julia),
            "kotlin" | "kt" | "kts" => Some(Lang::Kotlin),
            "lua" => Some(Lang::Lua),
            "nim" => Some(Lang::Nim),
            "perl" | "pl" => Some(Lang::Perl),
            "php" => Some(Lang::Php),
            "python" | "py" | "python3" => Some(Lang::Python),
            "r" => Some(Lang::R),
            "ruby" | "rb" => Some(Lang::Ruby),
            "rust" | "rs" => Some(Lang::Rust),
            "swift" => Some(Lang::Swift),
            "typescript" | "ts" => Some(Lang::Typescript),
            "zig" => Some(Lang::Zig),
            _ => None,
        }
    }
    fn available_list() -> &'static str {
        "bash, c, cpp, crystal, csharp, dart, elixir, go, groovy, haskell, java, javascript, julia, kotlin, lua, nim, perl, php, python, r, ruby, rust, swift, typescript, zig"
    }
}

fn lang_from_extension(ext: &str) -> Option<Lang> {
    let e = ext.to_ascii_lowercase();
    // ext includes dot? we pass without dot, lowercased
    match e.as_str() {
        "py" | "pyw" | "pyi" | "python" | "pyo" | "pyx" | "pxd" | "pyc" => Some(Lang::Python),
        "sh" | "bash" | "zsh" => Some(Lang::Bash),
        "js" | "mjs" | "cjs" | "jsx" => Some(Lang::Javascript),
        "ts" | "tsx" => Some(Lang::Typescript),
        "kt" | "kts" => Some(Lang::Kotlin),
        "cs" => Some(Lang::Csharp),
        "groovy" => Some(Lang::Groovy),
        "r" => Some(Lang::R),
        "jl" => Some(Lang::Julia),
        "hs" => Some(Lang::Haskell),
        "nim" => Some(Lang::Nim),
        "dart" => Some(Lang::Dart),
        "lua" => Some(Lang::Lua),
        "pl" | "pm" => Some(Lang::Perl),
        "php" => Some(Lang::Php),
        "rb" => Some(Lang::Ruby),
        "go" => Some(Lang::Go),
        "rs" => Some(Lang::Rust),
        "c" | "C" => None, // handle case-sensitive? Actually .C uppercase is c, .c is c
        "cpp" | "cc" | "cxx" | "hpp" | "hxx" => Some(Lang::Cpp),
        "java" => Some(Lang::Java),
        "swift" => Some(Lang::Swift),
        "zig" => Some(Lang::Zig),
        "cr" => Some(Lang::Crystal),
        "ex" | "exs" => Some(Lang::Elixir),
        _ => None,
    }
}

// Need case-sensitive for .C vs .c? Both map to c. And .R vs .r both R. So lowercasing is fine except .C vs .c both c anyway.
// But .C uppercase should be c, lowercased "c" also c, so fine.
// For extension mapping, we need to handle exact: .h -> python fallback, .c++ -> python fallback, etc. So only above map, rest fallback.

fn main() {
    let cmd = Command::new("run-kit")
        .about("Universal multi-language runner and REPL")
        .disable_version_flag(true)
        .arg(Arg::new("version").short('V').long("version").help("Print version information and exit").action(ArgAction::SetTrue))
        .arg(Arg::new("lang").short('l').long("lang").value_name("LANG").help("Explicitly choose the language to execute").action(ArgAction::Set))
        .arg(Arg::new("file").short('f').long("file").value_name("PATH").help("Execute code from the provided file path").action(ArgAction::Set))
        .arg(Arg::new("code").short('c').long("code").value_name("CODE").help("Execute the provided code snippet").action(ArgAction::Set))
        .arg(Arg::new("no-detect").long("no-detect").help("Disable heuristic language detection").action(ArgAction::SetTrue))
        .arg(Arg::new("ARGS").help("Positional arguments (language, code, or file)").num_args(0..));

    let matches = cmd.try_get_matches_from(std::env::args());
    let m = match matches {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    if m.get_flag("version") {
        print!("{}", VERSION_OUTPUT);
        std::process::exit(0);
    }
    // help is handled automatically by clap (ArgAction::Help). Our custom version flag is SetTrue, so --help still works via clap's auto help.

    let lang_opt: Option<String> = m.get_one::<String>("lang").cloned();
    let file_opt: Option<String> = m.get_one::<String>("file").cloned();
    let code_opt: Option<String> = m.get_one::<String>("code").cloned();
    let no_detect = m.get_flag("no-detect");
    let args: Vec<String> = m.get_many::<String>("ARGS").map(|v| v.cloned().collect()).unwrap_or_default();

    // Validate --code + --file
    if code_opt.is_some() && file_opt.is_some() {
        eprintln!("Error: --code/--inline cannot be combined with --file");
        std::process::exit(1);
    }
    if code_opt.is_some() && !args.is_empty() {
        eprintln!("Error: Unexpected positional arguments after specifying --code");
        std::process::exit(1);
    }
    if file_opt.is_some() && !args.is_empty() {
        eprintln!("Error: Unexpected positional arguments when --file is present");
        std::process::exit(1);
    }

    // Resolve explicit lang
    let explicit_lang: Option<Lang> = match &lang_opt {
        Some(s) => match Lang::from_str(s) {
            Some(l) => Some(l),
            None => {
                eprintln!("Error: Unknown language '{}'. Available languages: {}", s.to_ascii_lowercase(), Lang::available_list());
                std::process::exit(1);
            }
        },
        None => None,
    };

    // Handle --file
    if let Some(fpath) = file_opt {
        let lang = match explicit_lang {
            Some(l) => l,
            None => {
                // detect from extension, fallback python
                detect_lang_from_path(&fpath)
            }
        };
        // check unknown? already handled
        execute_file(&lang, &fpath);
        return;
    }

    // Handle --code
    if let Some(code) = code_opt {
        let lang = match explicit_lang {
            Some(l) => l,
            None => {
                if no_detect {
                    Lang::Python
                } else {
                    heuristic_detect(&code)
                }
            }
        };
        execute_code(&lang, &code, None);
        return;
    }

    // Handle positionals
    if !args.is_empty() {
        if args.len() == 1 {
            let single = &args[0];
            // Check if explicit lang present? Then single is code or file
            if let Some(el) = explicit_lang {
                // single is file if exists or has known ext? else code
                if is_file_path(single) {
                    execute_file(&el, single);
                } else {
                    execute_code(&el, single, None);
                }
                return;
            } else {
                // No explicit lang: check if single is file (exists or known ext) -> file mode with detected lang
                if is_file_path(single) {
                    let lang = detect_lang_from_path(single);
                    execute_file(&lang, single);
                    return;
                } else {
                    // Check if single is a language id? e.g., `run python` with no code -> REPL or stdin?
                    // If single is a known language and nothing else, treat as lang for REPL/stdin, not code
                    if let Some(l) = Lang::from_str(single) {
                        // This is `run python` with no code: read stdin or REPL
                        handle_stdin_or_repl(Some(l), no_detect);
                        return;
                    } else {
                        // code with heuristic or fallback
                        let lang = if no_detect { Lang::Python } else { heuristic_detect(single) };
                        execute_code(&lang, single, None);
                        return;
                    }
                }
            }
        } else {
            // multiple positionals
            // Check if first is lang?
            if explicit_lang.is_some() {
                // explicit lang + multiple positionals -> join as code? Actually earlier test showed `--lang python file extra` treated as code via -c (error shows python -c with joined). So join all as code.
                let joined = args.join(" ");
                execute_code(&explicit_lang.unwrap(), &joined, None);
                return;
            } else {
                if let Some(l) = Lang::from_str(&args[0]) {
                    // first is lang, rest is code or file?
                    if args.len() == 2 {
                        let second = &args[1];
                        if is_file_path(second) {
                            execute_file(&l, second);
