// Helper to find binary in PATH, returns absolute path if found
fn find_binary(names: &[&str]) -> Option<PathBuf> {
    if let Ok(path_var) = std::env::var("PATH") {
        for dir in path_var.split(':') {
            if dir.is_empty() { continue; }
            for name in names {
                let p = Path::new(dir).join(name);
                if p.is_file() {
                    // check executable? Just check exists
                    // Use access check via metadata
                    if let Ok(md) = std::fs::metadata(&p) {
                        #[cfg(unix)]
                        {
                            use std::os::unix::fs::PermissionsExt;
                            if md.permissions().mode() & 0o111 != 0 {
                                return Some(p);
                            } else {
                                // still consider? For our fakes, they are executable
                                continue;
                            }
                        }
                        #[cfg(not(unix))]
                        return Some(p);
                    }
                }
            }
        }
    }
    None
}

