// Python
fn exec_python_code(code: &str) {
    let py = find_binary(&["python3", "python"]);
    let py_path = match py {
        Some(p) => p,
        None => {
            // generic error
            eprintln!("Error: No such file or directory (os error 2)");
            std::process::exit(1);
        }
    };
    // version check (ignore)
    let _ = ProcCommand::new(&py_path).arg("--version").output();
    // run with -c
    let mut cmd = ProcCommand::new(&py_path);
    cmd.arg("-c").arg(code);
    // stdin forwarding: inherit stdin? For --code with piped stdin, need to forward stdin to child. Our stdin was already consumed? For execute_code via --code, stdin is still available (not consumed as code). So we should inherit stdin.
    // For stdin code case, stdin already consumed, so no forwarding needed (child stdin should be empty or inherit? Actually stdin code consumed, child should get empty stdin (or original stdin's remaining? But original stdin fully consumed, so empty).
    // To handle both, we will set stdin to inherit if stdin is not terminal and not consumed? Simpler: always inherit stdin via Stdio::inherit, except when code came from stdin (then stdin is EOF, inherit will be EOF anyway).
    // But need to handle program stdin forwarding for --code with piped input: e.g., echo Hello | run python --code "...read stdin..." should forward Hello. If we inherit, it will work (since stdin still has Hello? Wait for --code case, we didn't consume stdin, so stdin still has Hello, inherit works).
    // For stdin-code case, we consumed stdin, so inherit would be EOF (since we read all). That's correct (program gets no input, but code already consumed stdin, so program shouldn't get stdin anyway).
    // However, after reading stdin via read_to_string, stdin is at EOF, inherit will give EOF. Good.
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    let status = cmd.status().unwrap_or_else(|e| {
        eprintln!("Error: No such file or directory (os error 2)");
        std::process::exit(1);
    });
    std::process::exit(status.code().unwrap_or(1));
}

