                                    }
                                }
                            }
                            b'H' | b'F' | b'Z' => {
                                // Home, End, etc. Ignore for now
                            }
                            _ => {}
                        }
                    }
                } else if b2[0] == b'O' {
                    // SS3? e.g., ESC O ... Ignore
                    if wait_for_input(100) {
                        let mut b3 = [0u8;1];
                        unsafe { libc::read(stdin_fd, b3.as_mut_ptr() as *mut libc::c_void, 1) };
                    }
                }
            }
            continue;
        } else if b == 0x01 {
            // Ctrl-A: Home
            cursor = 0;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x05 {
            // Ctrl-E: End
            cursor = buffer.chars().count();
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x0b {
            // Ctrl-K: kill to end? Not sure if supported. Ignore? Let's implement: delete from cursor to end
            let mut chars: Vec<char> = buffer.chars().collect();
            chars.truncate(cursor);
            buffer = chars.into_iter().collect();
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x15 {
            // Ctrl-U: clear line? Implement as clear buffer
            buffer.clear();
            cursor = 0;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x0c {
            // Ctrl-L: clear screen? Ignore
            continue;
        } else if b < 0x20 {
            // Other control: ignore
            continue;
        } else {
            // Printable (including UTF-8? Need to handle multi-byte UTF-8: if b >= 0x80, need to read continuation bytes)
            let mut bytes = vec![b];
            if b >= 0xC0 {
                let extra = if b >= 0xF0 { 3 } else if b >= 0xE0 { 2 } else { 1 };
                for _ in 0..extra {
                    let mut nb = [0u8;1];
                    unsafe { libc::read(stdin_fd, nb.as_mut_ptr() as *mut libc::c_void, 1) };
                    bytes.push(nb[0]);
                }
            }
            let s = String::from_utf8_lossy(&bytes).to_string();
            // Insert at cursor
            let mut chars: Vec<char> = buffer.chars().collect();
            let insert_chars: Vec<char> = s.chars().collect();
            for (i, ch) in insert_chars.iter().enumerate() {
                chars.insert(cursor + i, *ch);
            }
            cursor += insert_chars.len();
            buffer = chars.into_iter().collect();
            hist_idx = None;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        }
    }
}

fn wait_for_input(timeout_ms: u64) -> bool {
    unsafe {
        let mut fds: libc::fd_set = std::mem::zeroed();
        libc::FD_ZERO(&mut fds);
        libc::FD_SET(0, &mut fds);
        let mut tv = libc::timeval {
            tv_sec: (timeout_ms / 1000) as libc::time_t,
            tv_usec: ((timeout_ms % 1000) * 1000) as libc::suseconds_t,
        };
        let ret = libc::select(1, &mut fds, std::ptr::null_mut(), std::ptr::null_mut(), &mut tv);
        ret > 0
    }
}

fn enable_raw_mode() -> Option<libc::termios> {
    unsafe {
        let mut orig: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(0, &mut orig) != 0 {
            return None;
        }
        let mut raw = orig.clone();
        // cfmakeraw equivalent
        raw.c_iflag &= !(libc::BRKINT | libc::ICRNL | libc::INPCK | libc::ISTRIP | libc::IXON);
        raw.c_oflag &= !(libc::OPOST);
        raw.c_cflag |= libc::CS8;
        raw.c_lflag &= !(libc::ECHO | libc::ICANON | libc::IEXTEN | libc::ISIG);
        raw.c_cc[libc::VMIN as usize] = 1;
        raw.c_cc[libc::VTIME as usize] = 0;
        if libc::tcsetattr(0, libc::TCSANOW, &raw) != 0 {
            return None;
        }
        Some(orig)
    }
}
fn restore_raw_mode(orig: Option<libc::termios>) {
    if let Some(o) = orig {
        unsafe {
            libc::tcsetattr(0, libc::TCSANOW, &o);
        }
    }
}
