                    if wait_for_input(100) {
                        let mut b3 = [0u8;1];
                        unsafe { libc::read(stdin_fd, b3.as_mut_ptr() as *mut libc::c_void, 1) };
                        match b3[0] {
                            b'D' => {
                                // Left
                                if cursor > 0 {
                                    cursor -= 1;
                                    redraw(&current_prompt, &buffer, cursor);
                                }
                            }
                            b'C' => {
                                // Right
                                let len = buffer.chars().count();
                                if cursor < len {
                                    cursor += 1;
                                    redraw(&current_prompt, &buffer, cursor);
                                }
                            }
                            b'A' => {
                                // Up: history prev
                                let hist = history.entry(current_lang.canonical().to_string()).or_insert(Vec::new());
                                if !hist.is_empty() {
                                    if hist_idx.is_none() {
                                        hist_saved = buffer.clone();
                                        hist_idx = Some(hist.len());
                                    }
                                    if let Some(idx) = hist_idx {
                                        if idx > 0 {
                                            let new_idx = idx - 1;
                                            hist_idx = Some(new_idx);
                                            buffer = hist[new_idx].clone();
                                            cursor = buffer.chars().count();
                                            redraw(&current_prompt, &buffer, cursor);
                                        }
                                    }
                                }
                            }
                            b'B' => {
                                // Down: history next
                                if let Some(idx) = hist_idx {
                                    let hist = history.get(current_lang.canonical()).cloned().unwrap_or_default();
                                    if idx + 1 < hist.len() {
                                        let new_idx = idx + 1;
                                        hist_idx = Some(new_idx);
                                        buffer = hist[new_idx].clone();
                                        cursor = buffer.chars().count();
                                        redraw(&current_prompt, &buffer, cursor);
                                    } else {
                                        hist_idx = None;
                                        buffer = hist_saved.clone();
                                        cursor = buffer.chars().count();
                                        redraw(&current_prompt, &buffer, cursor);
                                    }
                                }
                            }
                            b'2' => {
                                // Possibly bracketed paste start "200~" or delete "2~"? Need to read more
                                // Peek next?
                                if wait_for_input(100) {
                                    let mut b4 = [0u8;1];
                                    unsafe { libc::read(stdin_fd, b4.as_mut_ptr() as *mut libc::c_void, 1) };
                                    if b4[0] == b'0' {
                                        // Could be 200~ (paste start)
                                        // Read "0~" ?
                                        let mut rest = [0u8;2];
                                        // Try to read 2 bytes
                                        unsafe {
                                            // Use blocking read for 2 bytes with timeout?
                                            // For simplicity, read 2 bytes
                                            let mut tmp = [0u8;2];
                                            // Use read with select?
                                            // We'll just read
                                            libc::read(stdin_fd, tmp.as_mut_ptr() as *mut libc::c_void, 2);
                                            rest = tmp;
                                        }
                                        if rest == [b'0', b'~'] {
                                            // Bracketed paste start: read until 201~
                                            let mut paste = Vec::new();
                                            loop {
                                                let mut pb = [0u8;1];
                                                let nn = unsafe { libc::read(stdin_fd, pb.as_mut_ptr() as *mut libc::c_void, 1) };
                                                if nn <= 0 { break; }
                                                // Check for end marker ESC [ 2 0 1 ~
                                                if pb[0] == 0x1b {
                                                    // Peek next 4?
                                                    let mut seq = [0u8;4];
                                                    // Try to read 4 bytes with timeout?
                                                    // Use select to check?
                                                    // For simplicity, read 4 bytes blocking (since paste end should follow)
                                                    // But need to handle case where ESC is part of paste? Unlikely.
                                                    // Read 4 bytes
                                                    let mut tmp = [0u8;4];
                                                    unsafe { libc::read(stdin_fd, tmp.as_mut_ptr() as *mut libc::c_void, 4) };
                                                    if tmp == [b'[', b'2', b'0', b'1'] {
                                                        // Need one more ~ ?
                                                        let mut tilde = [0u8;1];
                                                        unsafe { libc::read(stdin_fd, tilde.as_mut_ptr() as *mut libc::c_void, 1) };
                                                        if tilde[0] == b'~' {
                                                            break;
                                                        } else {
                                                            paste.push(0x1b);
                                                            paste.extend_from_slice(&tmp);
                                                            paste.push(tilde[0]);
                                                        }
                                                    } else {
                                                        paste.push(0x1b);
                                                        paste.extend_from_slice(&tmp);
                                                    }
                                                } else {
                                                    paste.push(pb[0]);
                                                }
                                            }
                                            let paste_str = String::from_utf8_lossy(&paste).to_string();
                                            // Insert at cursor
                                            let mut chars: Vec<char> = buffer.chars().collect();
                                            let paste_chars: Vec<char> = paste_str.chars().collect();
                                            for (i, ch) in paste_chars.iter().enumerate() {
                                                chars.insert(cursor + i, *ch);
                                            }
                                            cursor += paste_chars.len();
                                            buffer = chars.into_iter().collect();
                                            redraw(&current_prompt, &buffer, cursor);
                                        }
                                    } else if b4[0] == b'~' {
                                        // Delete? Actually ESC[2~ is insert, ESC[3~ is delete. We got ESC[2... but b3 is '2', b4 is '~'? That would be insert? Ignore.
                                    }
                                }
                            }
                            b'3' => {
                                // Delete key ESC[3~ : delete at cursor
                                if wait_for_input(100) {
                                    let mut b4 = [0u8;1];
                                    unsafe { libc::read(stdin_fd, b4.as_mut_ptr() as *mut libc::c_void, 1) };
                                    if b4[0] == b'~' {
                                        let mut chars: Vec<char> = buffer.chars().collect();
                                        if cursor < chars.len() {
                                            chars.remove(cursor);
                                            buffer = chars.into_iter().collect();
                                            redraw(&current_prompt, &buffer, cursor);
                                        }
                                    }
                                }
                            }
                            b'H' | b'F' | b'Z' => {
                                // Home, End, etc. Ignore for now
                            }
                            _ => {}
                        }
                    }
                } else if b2[0] == b'O' {
                    // SS3? e.g., ESC O ... Ignore
                    if wait_for_input(100) {
                        let mut b3 = [0u8;1];
                        unsafe { libc::read(stdin_fd, b3.as_mut_ptr() as *mut libc::c_void, 1) };
                    }
                }
            }
            continue;
        } else if b == 0x01 {
            // Ctrl-A: Home
            cursor = 0;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x05 {
            // Ctrl-E: End
            cursor = buffer.chars().count();
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x0b {
            // Ctrl-K: kill to end? Not sure if supported. Ignore? Let's implement: delete from cursor to end
            let mut chars: Vec<char> = buffer.chars().collect();
            chars.truncate(cursor);
            buffer = chars.into_iter().collect();
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x15 {
            // Ctrl-U: clear line? Implement as clear buffer
            buffer.clear();
            cursor = 0;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        } else if b == 0x0c {
            // Ctrl-L: clear screen? Ignore
            continue;
        } else if b < 0x20 {
            // Other control: ignore
            continue;
        } else {
            // Printable (including UTF-8? Need to handle multi-byte UTF-8: if b >= 0x80, need to read continuation bytes)
            let mut bytes = vec![b];
            if b >= 0xC0 {
                let extra = if b >= 0xF0 { 3 } else if b >= 0xE0 { 2 } else { 1 };
                for _ in 0..extra {
                    let mut nb = [0u8;1];
                    unsafe { libc::read(stdin_fd, nb.as_mut_ptr() as *mut libc::c_void, 1) };
                    bytes.push(nb[0]);
                }
            }
            let s = String::from_utf8_lossy(&bytes).to_string();
            // Insert at cursor
            let mut chars: Vec<char> = buffer.chars().collect();
            let insert_chars: Vec<char> = s.chars().collect();
            for (i, ch) in insert_chars.iter().enumerate() {
                chars.insert(cursor + i, *ch);
            }
            cursor += insert_chars.len();
            buffer = chars.into_iter().collect();
            hist_idx = None;
            redraw(&current_prompt, &buffer, cursor);
            continue;
        }
    }
}

fn wait_for_input(timeout_ms: u64) -> bool {
    unsafe {
        let mut fds: libc::fd_set = std::mem::zeroed();
        libc::FD_ZERO(&mut fds);
        libc::FD_SET(0, &mut fds);
        let mut tv = libc::timeval {
            tv_sec: (timeout_ms / 1000) as libc::time_t,
            tv_usec: ((timeout_ms % 1000) * 1000) as libc::suseconds_t,
        };
        let ret = libc::select(1, &mut fds, std::ptr::null_mut(), std::ptr::null_mut(), &mut tv);
        ret > 0
    }
}

fn enable_raw_mode() -> Option<libc::termios> {
    unsafe {
        let mut orig: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(0, &mut orig) != 0 {
            return None;
        }
        let mut raw = orig.clone();
        // cfmakeraw equivalent
        raw.c_iflag &= !(libc::BRKINT | libc::ICRNL | libc::INPCK | libc::ISTRIP | libc::IXON);
        raw.c_oflag &= !(libc::OPOST);
        raw.c_cflag |= libc::CS8;
        raw.c_lflag &= !(libc::ECHO | libc::ICANON | libc::IEXTEN | libc::ISIG);
        raw.c_cc[libc::VMIN as usize] = 1;
        raw.c_cc[libc::VTIME as usize] = 0;
        if libc::tcsetattr(0, libc::TCSANOW, &raw) != 0 {
            return None;
        }
        Some(orig)
    }
}
fn restore_raw_mode(orig: Option<libc::termios>) {
    if let Some(o) = orig {
        unsafe {
            libc::tcsetattr(0, libc::TCSANOW, &o);
        }
    }
}
