fn is_python_expression(code: &str) -> bool {
    let t = code.trim();
    if t.is_empty() { return false; }
    // If contains newline, multi-line? Probably statement.
    if t.contains('\n') { return false; }
    // Keywords that indicate statement
    let keywords = ["import ", "from ", "def ", "class ", "for ", "while ", "if ", "elif ", "else", "try:", "except", "with ", "return", "break", "continue", "pass", "raise ", "assert ", "del ", "global ", "nonlocal ", "yield", "async ", "await "];
    for kw in keywords {
        if t.starts_with(kw) { return false; }
    }
    // Assignment (but not ==, !=, <=, >=, :=, =>? Check for "=" not part of "==" etc.)
    // Simple: if contains "=" and not "==" and not "!=" etc., then assignment => not expression.
    // Actually `x=10` contains "=", `x==1` contains "==" but is expression (comparison) that should print True/False. So need to distinguish.
    // Check for single "=" not in "==", "!=", "<=", ">=", ":=", "=>", "->"?
    // For simplicity, if contains "=" and not contains "==" and not contains "!=" and not contains "<=" and not contains ">=" and not contains ":=" {
    //   return false (assignment)
    // }
    if t.contains('=') {
        // Check if it's comparison vs assignment: if contains "==" then it's expression (comparison), not assignment.
        // So only return false if "=" present but "==" not present and other combos not present?
        // Actually `x=10` has "=", no "==", so assignment => false.
        // `x==1` has "==", so expression => true.
        // `x!=1` has "!=", but also "=", but it's expression => true. So need to check for "==", "!=", "<=", ">=" first.
        let is_comparison = t.contains("==") || t.contains("!=") || t.contains("<=") || t.contains(">=") || t.contains(":=") || t.contains("->");
        if !is_comparison && t.contains('=') {
            return false;
        }
    }
    // If contains ";"? Probably statement.
    if t.contains(';') { return false; }
    // If starts with "print" or "exec" etc., it's already statement that prints, not expression needing extra print (since output already non-empty, we wouldn't be here). But for safety, if t starts with "print", return false (don't double print).
    if t.starts_with("print") { return false; }
    // Otherwise, treat as expression
    true
}

