def norm2(s):
    s=re.sub(r'/tmp/run-[a-z\-]*[A-Za-z0-9]{6}/[A-Za-z0-9_\.\-]+', '/TMP/FILE', s)
    s=re.sub(r'/tmp/run-[a-z\-]*[A-Za-z0-9]{6}', '/TMP', s)
    s=re.sub(r'/tmp/\.tmp[A-Za-z0-9]+', '/TMP', s)
    s=re.sub(r'\(\d+ms\)', '(Tms)', s)
    return s
def ro(a,s=None, env=None):
